   "codice": "extends RefCounted


func run():
	var total: int = 0
	for i in range(3):
		total += i
	return total
",
   "domanda": "Quanto vale `total` alla fine?",
   "spiegazione": "`range(3)` genera la sequenza di numeri interi 0, 1 e 2. Il ciclo somma ogni numero a `total`: 0 + 0 = 0, poi 0 + 1 = 1, e infine 1 + 2 = 3."
  },
