   "codice": "extends RefCounted


func run():
	var count: int = 0
	for i in range(1, 6, 2):
		count += 1
	return count
",
   "domanda": "Quanto vale `count` alla fine?",
   "spiegazione": "`range(1, 6, 2)` parte da 1, arriva prima di 6 procedendo a passi di 2. I numeri generati sono 1, 3 e 5. Il blocco del ciclo viene eseguito esattamente 3 volte, quindi `count` arriva a 3."
  },
